  "checks": [
    {
      "id": "AMBIGUITY",
      "result": "PASS",
      "severity": "Major",
      "finding": "Requirements REQ-001–006 distinguish full fallback, selected execution and aggregation failure. The Model configuration precedence section defines source ordering, implicit pinning, policy conflicts and native alignment; TEST-152–162 make these outcomes observable. TEST-131–133 distinguish configured identity from actual execution evidence."
    },
    {
      "id": "CONTRADICTION",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Requirements and acceptance branches consistently preserve required contexts, immutable releases, authorization and historical evidence. REQ-016 and TEST-107/133 consistently block gates requiring unavailable actual-ID proof while permitting explicitly unverified ordinary runs. No conforming amendment declaration is present, but investigation references baseline research and prior-feature evidence rather than claiming this feature has progressed beyond specification approval."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Acceptance TEST-001–078 cover revision mismatches, unusual paths, empty/unknown changes, missing or duplicate evidence, cancellations, reruns, cache corruption and event isolation. TEST-083–110 and TEST-131–162 cover incomplete discovery, unavailable models, identity mismatches, unsupported telemetry and conflicting or malformed configuration."
    },
    {
      "id": "ASSUMPTIONS-RESOLVABLE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Investigation INV-001–014 supplies baseline observations and source references. Requirements Assumptions identifies required revalidation before design review/adoption. OQ-001 and OQ-002 identify owners, bounded verification limitations and explicit full/unverified/unsupported behavior without inventing successful external validation."
    },
    {
      "id": "APPROVAL-BOUNDARY",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Requirements Non-goals, Roles and Permissions, and REQ-010/017/018/020 prohibit external protection changes, automatic merges, unauthorized sends and mutable release tags. TEST-038/130 verifies exact-commit immutable delivery; TEST-082/115/121/137 verifies consent, reviewed adoption, prior identity reservation and unchanged automation boundaries."
    },
    {
      "id": "DOWNSTREAM-READINESS",
      "result": "PASS",
      "severity": "Major",
      "finding": "REQ-001–020 map to AC-001–020 with explicit positive and negative branches. Conservative CI fallback, model-policy resolution, launch integration, evidence limitations and release conditions are specified sufficiently for downstream design without inventing product behavior. Reservation receipt, input hashes and precheck bindings verified."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Major",
      "finding": "The host states that the target project has no domain/ directory; investigation Bootstrap Context independently records its absence. The check's applicability condition is not met."
    }
  ]
